-- =============================================================================
-- Migration: enable_rls
-- =============================================================================
-- Enables Row-Level Security on every tenant-owned table and installs the
-- helper SQL functions that RLS policies reference.
--
-- This migration is hand-written (not generated by Prisma) because Prisma does
-- not model RLS. It runs AFTER the `init` migration that creates all tables.
-- =============================================================================


-- =============================================================================
-- HELPER FUNCTIONS
-- =============================================================================

CREATE OR REPLACE FUNCTION public.current_user_id()
  RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER
AS $$ SELECT auth.uid(); $$;

CREATE OR REPLACE FUNCTION public.current_school_id()
  RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER
AS $$
  SELECT school_id FROM public.users
  WHERE auth_id = auth.uid() AND deleted_at IS NULL LIMIT 1;
$$;

CREATE OR REPLACE FUNCTION public.current_user_role()
  RETURNS text LANGUAGE sql STABLE SECURITY DEFINER
AS $$
  SELECT role::text FROM public.users
  WHERE auth_id = auth.uid() AND deleted_at IS NULL LIMIT 1;
$$;

CREATE OR REPLACE FUNCTION public.guardian_student_ids()
  RETURNS uuid[] LANGUAGE sql STABLE SECURITY DEFINER
AS $$
  SELECT COALESCE(ARRAY(
    SELECT g.student_id FROM public.guardians g
    JOIN public.users u ON u.id = g.user_id
    WHERE u.auth_id = auth.uid() AND u.deleted_at IS NULL
  ), '{}'::uuid[]);
$$;


-- =============================================================================
-- ENABLE RLS
-- =============================================================================

ALTER TABLE public.schools             ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.users               ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.students            ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.teachers            ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.guardians           ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.classes             ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.subjects            ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.subject_assignments ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.terms               ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.timetable_slots     ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.attendance_records  ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.fee_balances        ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.announcements       ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.audit_logs          ENABLE ROW LEVEL SECURITY;


-- =============================================================================
-- SCHOOLS
-- =============================================================================

CREATE POLICY "schools_select_own" ON public.schools FOR SELECT
  USING (id = public.current_school_id());


-- =============================================================================
-- USERS
-- =============================================================================

CREATE POLICY "users_select_same_school" ON public.users FOR SELECT
  USING (school_id = public.current_school_id() AND deleted_at IS NULL);

CREATE POLICY "users_insert_admin_only" ON public.users FOR INSERT
  WITH CHECK (school_id = public.current_school_id() AND public.current_user_role() = 'ADMIN');

CREATE POLICY "users_update_admin_only" ON public.users FOR UPDATE
  USING (school_id = public.current_school_id() AND public.current_user_role() = 'ADMIN')
  WITH CHECK (school_id = public.current_school_id() AND public.current_user_role() = 'ADMIN');


-- =============================================================================
-- STUDENTS
-- =============================================================================

CREATE POLICY "students_select" ON public.students FOR SELECT
  USING (
    school_id = public.current_school_id() AND (
      public.current_user_role() IN ('ADMIN', 'TEACHER')
      OR (public.current_user_role() = 'STUDENT' AND user_id = (
        SELECT id FROM public.users WHERE auth_id = auth.uid() AND deleted_at IS NULL LIMIT 1
      ))
      OR (public.current_user_role() = 'PARENT' AND id = ANY(public.guardian_student_ids()))
    )
  );

CREATE POLICY "students_insert_admin_only" ON public.students FOR INSERT
  WITH CHECK (school_id = public.current_school_id() AND public.current_user_role() = 'ADMIN');

CREATE POLICY "students_update_admin_only" ON public.students FOR UPDATE
  USING (school_id = public.current_school_id() AND public.current_user_role() = 'ADMIN')
  WITH CHECK (school_id = public.current_school_id() AND public.current_user_role() = 'ADMIN');


