-- =============================================================================

CREATE POLICY "guardians_select_admin" ON public.guardians FOR SELECT
  USING (
    public.current_user_role() = 'ADMIN' AND
    student_id IN (SELECT id FROM public.students WHERE school_id = public.current_school_id())
  );

CREATE POLICY "guardians_select_own_parent" ON public.guardians FOR SELECT
  USING (
    public.current_user_role() = 'PARENT' AND
    user_id = (SELECT id FROM public.users WHERE auth_id = auth.uid() AND deleted_at IS NULL LIMIT 1)
  );

CREATE POLICY "guardians_insert_admin_only" ON public.guardians FOR INSERT
  WITH CHECK (
    public.current_user_role() = 'ADMIN' AND
    student_id IN (SELECT id FROM public.students WHERE school_id = public.current_school_id())
  );

CREATE POLICY "guardians_update_admin_only" ON public.guardians FOR UPDATE
  USING (
    public.current_user_role() = 'ADMIN' AND
    student_id IN (SELECT id FROM public.students WHERE school_id = public.current_school_id())
  )
  WITH CHECK (
    public.current_user_role() = 'ADMIN' AND
    student_id IN (SELECT id FROM public.students WHERE school_id = public.current_school_id())
  );


