-- =============================================================================
-- ATTENDANCE_RECORDS
-- =============================================================================

CREATE POLICY "attendance_records_select" ON public.attendance_records FOR SELECT
  USING (
    school_id = public.current_school_id() AND (
      public.current_user_role() = 'ADMIN'
      OR (public.current_user_role() = 'TEACHER' AND class_id IN (
        SELECT sa.class_id FROM public.subject_assignments sa
        JOIN public.teachers t ON t.id = sa.teacher_id
        JOIN public.users u ON u.id = t.user_id
        WHERE u.auth_id = auth.uid() AND u.deleted_at IS NULL
      ))
      OR (public.current_user_role() = 'STUDENT' AND student_id = (
        SELECT s.id FROM public.students s
        JOIN public.users u ON u.id = s.user_id
        WHERE u.auth_id = auth.uid() AND u.deleted_at IS NULL LIMIT 1
      ))
      OR (public.current_user_role() = 'PARENT' AND student_id = ANY(public.guardian_student_ids()))
    )
  );

CREATE POLICY "attendance_records_insert_teacher_or_admin" ON public.attendance_records FOR INSERT
  WITH CHECK (
    school_id = public.current_school_id() AND (
      public.current_user_role() = 'ADMIN'
      OR (public.current_user_role() = 'TEACHER' AND class_id IN (
        SELECT sa.class_id FROM public.subject_assignments sa
        JOIN public.teachers t ON t.id = sa.teacher_id
        JOIN public.users u ON u.id = t.user_id
        WHERE u.auth_id = auth.uid() AND u.deleted_at IS NULL
      ))
    )
  );

CREATE POLICY "attendance_records_update_teacher_or_admin" ON public.attendance_records FOR UPDATE
  USING (
    school_id = public.current_school_id() AND (
      public.current_user_role() = 'ADMIN'
      OR (public.current_user_role() = 'TEACHER' AND class_id IN (
        SELECT sa.class_id FROM public.subject_assignments sa
        JOIN public.teachers t ON t.id = sa.teacher_id
        JOIN public.users u ON u.id = t.user_id
        WHERE u.auth_id = auth.uid() AND u.deleted_at IS NULL
      ))
    )
  )
  WITH CHECK (
    school_id = public.current_school_id() AND (
      public.current_user_role() = 'ADMIN'
      OR (public.current_user_role() = 'TEACHER' AND class_id IN (
        SELECT sa.class_id FROM public.subject_assignments sa
        JOIN public.teachers t ON t.id = sa.teacher_id
        JOIN public.users u ON u.id = t.user_id
        WHERE u.auth_id = auth.uid() AND u.deleted_at IS NULL
      ))
    )
  );


