  WITH CHECK (school_id = public.current_school_id() AND public.current_user_role() = 'ADMIN');


-- =============================================================================
-- ANNOUNCEMENTS
-- =============================================================================

CREATE POLICY "announcements_select" ON public.announcements FOR SELECT
  USING (
    school_id = public.current_school_id() AND (
      audience = 'SCHOOL_WIDE'
      OR public.current_user_role() = 'ADMIN'
      OR (audience = 'GRADE' AND target_grade_level IN (
        SELECT c.grade_level FROM public.classes c
        JOIN public.students s ON s.current_class_id = c.id
        JOIN public.users u ON u.id = s.user_id
        WHERE u.auth_id = auth.uid() AND u.deleted_at IS NULL
        UNION
        SELECT c.grade_level FROM public.classes c
        JOIN public.students s ON s.current_class_id = c.id
        WHERE s.id = ANY(public.guardian_student_ids())
        UNION
        SELECT DISTINCT c.grade_level FROM public.timetable_slots ts
        JOIN public.classes c ON c.id = ts.class_id
        JOIN public.teachers t ON t.id = ts.teacher_id
        JOIN public.users u ON u.id = t.user_id
        WHERE u.auth_id = auth.uid() AND u.deleted_at IS NULL
      ))
      OR (audience = 'CLASS' AND target_class_id IN (
        SELECT s.current_class_id FROM public.students s
        JOIN public.users u ON u.id = s.user_id
        WHERE u.auth_id = auth.uid() AND u.deleted_at IS NULL
        UNION
        SELECT current_class_id FROM public.students
        WHERE id = ANY(public.guardian_student_ids())
        UNION
        SELECT DISTINCT class_id FROM public.timetable_slots ts
        JOIN public.teachers t ON t.id = ts.teacher_id
        JOIN public.users u ON u.id = t.user_id
        WHERE u.auth_id = auth.uid() AND u.deleted_at IS NULL
      ))
    )
  );

CREATE POLICY "announcements_insert_admin_only" ON public.announcements FOR INSERT
  WITH CHECK (school_id = public.current_school_id() AND public.current_user_role() = 'ADMIN');

CREATE POLICY "announcements_update_admin_only" ON public.announcements FOR UPDATE
  USING (school_id = public.current_school_id() AND public.current_user_role() = 'ADMIN')
  WITH CHECK (school_id = public.current_school_id() AND public.current_user_role() = 'ADMIN');

CREATE POLICY "announcements_delete_admin_only" ON public.announcements FOR DELETE
  USING (school_id = public.current_school_id() AND public.current_user_role() = 'ADMIN');


-- =============================================================================
-- AUDIT_LOGS  (append-only — no UPDATE/DELETE policies)
-- =============================================================================

CREATE POLICY "audit_logs_select_admin" ON public.audit_logs FOR SELECT
  USING (public.current_user_role() = 'ADMIN' AND school_id = public.current_school_id());

CREATE POLICY "audit_logs_select_own" ON public.audit_logs FOR SELECT
  USING (user_id = (
    SELECT id FROM public.users WHERE auth_id = auth.uid() AND deleted_at IS NULL LIMIT 1
  ));

CREATE POLICY "audit_logs_insert_own_school" ON public.audit_logs FOR INSERT
  WITH CHECK (school_id = public.current_school_id() OR school_id IS NULL);
